#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
rows() { grep -vc '^#' "$t"; }
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(rows)" = 2 ] && grep -q 'z$' "$t" && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
for d in 2025/06/01 2025-13-01 2025-01-32; do
  ARCHIVE=$t bash tools/purge-archive --before "$d" >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date $d should exit 2"; fail=1; }
done
[ "$(rows)" = 2 ] || { echo "a malformed date deleted rows"; fail=1; }
u=$(ARCHIVE=$t bash tools/purge-archive 2>&1 >/dev/null)
[ "$u" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage output: $u"; fail=1; }
rm -f "$t"; exit $fail

