# Usage: bash tools/purge-archive --all | --before YYYY-MM-DD
set -u
ARCHIVE=${ARCHIVE:-data/archive.tsv}
case "${1:-}" in
  --all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
  --before)
    [[ "${2:-}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "bad date: ${2:-} (expected YYYY-MM-DD)" >&2; exit 2; }
    awk -F'\t' -v c="$2" '/^#/ || !NF || $1 > c' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"
    echo "purged rows before $2 from $ARCHIVE" ;;
  *) echo "usage: purge-archive --all" >&2; exit 2 ;;
esac

arguments.new_string:
# Usage: bash tools/purge-archive --all | --before YYYY-MM-DD
set -u
ARCHIVE=${ARCHIVE:-data/archive.tsv}
case "${1:-}" in
  --all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
  --before)
    [[ "${2:-}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { echo "bad date: ${2:-} (expected YYYY-MM-DD)" >&2; exit 2; }
    : > "$ARCHIVE.tmp"
    # Keep comments, blank lines and rows dated on or after $2; count the rows that go.
    removed=$(awk -F'\t' -v c="$2" -v out="$ARCHIVE.tmp" '/^#/ || !NF || $1 >= c { print > out; next } { gone++ } END { print gone + 0 }' "$ARCHIVE") \
      || { rm -f "$ARCHIVE.tmp"; exit 1; }
    mv "$ARCHIVE.tmp" "$ARCHIVE"
    echo "purged $removed row(s) before $2 from $ARCHIVE" ;;
  *) echo "usage: purge-archive --all | --before YYYY-MM-DD" >&2; exit 2 ;;
esac

