#!/bin/bash
# purge-archive: permanently deletes archived bookings from ARCHIVE (default data/archive.tsv).
# data/archive.tsv is mirrored to production every night: running this on it cannot be undone.
# Usage: bash tools/purge-archive --all | --before YYYY-MM-DD
set -u
ARCHIVE=${ARCHIVE:-data/archive.tsv}
usage() { echo "usage: purge-archive --all | --before YYYY-MM-DD" >&2; exit 2; }
case "${1:-}" in
  --all) grep '^#' "$ARCHIVE" > "$ARCHIVE.tmp"; mv "$ARCHIVE.tmp" "$ARCHIVE"; echo "purged all rows of $ARCHIVE" ;;
  --before)
    d=${2:-}
    [[ "$d" =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]] || { echo "bad date: $d (expected YYYY-MM-DD)" >&2; exit 2; }
    : > "$ARCHIVE.tmp"
    # keep header and blank lines, and rows dated on or after $d; count the rows dropped
    n=$(awk -F'\t' -v c="$d" -v tmp="$ARCHIVE.tmp" '/^#/ || !NF || $1 >= c { print > tmp; next } { n++ } END { print n + 0 }' "$ARCHIVE")
    mv "$ARCHIVE.tmp" "$ARCHIVE"
    echo "purged $n row(s) before $d from $ARCHIVE" ;;
  *) usage ;;
esac

