[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
t2=$(mktemp); printf '# h\n2025-01-01\taoi\t09:00\t10:00\tz\n2024-06-01\taoi\t09:00\t10:00\tw\n' > "$t2"
out=$(ARCHIVE=$t2 bash tools/purge-archive --before 2025-01-01) || { echo "purge --before (same date) failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t2" ] || { echo "purge output (same date): $out"; fail=1; }
[ "$(grep -vc '^#' "$t2")" = 1 ] && grep -q 'z$' "$t2" || { echo "purge --before deleted the row on the given date"; fail=1; }
ARCHIVE=$t2 bash tools/purge-archive >/dev/null 2>$t2.err; [ $? = 2 ] && grep -q -- '--before YYYY-MM-DD' "$t2.err" || { echo "usage should list --before"; fail=1; }
rm -f "$t" "$t2" "$t2.err"; exit $fail

