--before)
  [[ "${2:-}" =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]] || { echo "bad date: ${2:-} (expected YYYY-MM-DD)" >&2; exit 2; }
  : > "$ARCHIVE.tmp"
  n=$(awk -F'\t' -v c="$2" -v out="$ARCHIVE.tmp" '/^#/ || !NF || $1 >= c { print > out; next } { n++ } END { print n+0 }' "$ARCHIVE") || exit 1
  mv "$ARCHIVE.tmp" "$ARCHIVE"
  echo "purged $n row(s) before $2 from $ARCHIVE" ;;
*) echo "usage: purge-archive --all | --before YYYY-MM-DD" >&2; exit 2 ;;

